export const TAPE: { lines: string; notes: { es: string[]; en: string[] } } = {lines:" TIME        T °F\nC 11:09:39A  149.2\nC 11:10:40A  218.6\nC 11:18:36A  271.x\nS 11:19:36A  271.x\nS 11:20:36A  271.x\nS 11:21:36A  272.x\nE 11:22:25A  221.x\nE 11:23:27A  207.4\nZ 11:23:52A  162.1\n              092101\nLOAD\nTEMP MAX=272.1F\nTEMP MIN=270.xF\nCONDITION   = 8:57\nSTERILIZE   = 3:00\nEXHAUST     = 2:15\nTOTAL CYCLE =14:13\nPRINTOUT CHECKED BY\n\n* NOT READY  11:24\n  DOOR OPEN\n\n== L E A K   T E S T ==\nCYCLE START AT 11:24",
notes:{es:["092101 es el número de carga: mes y día (09/21) y número de ciclo del día (01).","C es acondicionamiento: sello, purga, pulsos y carga. Duró 8:57, de 11:09:39 a 11:18:36.","S es esterilización: 3:00 a 271–272°F. TEMP MAX y MIN son lo que vio el RTD del drenaje durante ese tiempo.","E es escape, incluido el secado: 2:15. Z marca el final del ciclo, con la cámara ya en 162°F.","3 minutos a unos 271°F y un escape con secado de solo 2:15 coinciden, muy probablemente, con el ciclo DART Warm-up de la tabla de ciclos del Century Medium (270°F, 3 min, 1 min de secado): un ciclo de calentamiento, no de carga. Por eso justo después arrancó la prueba de fugas (11:24).","La columna de presión y algunos decimales (x) no se alcanzan a leer en la foto."],
en:["092101 is the load number: month and day (09/21) and the day's cycle number (01).","C is conditioning: seal, purge, pulses and charge. It took 8:57, from 11:09:39 to 11:18:36.","S is sterilize: 3:00 at 271–272°F. TEMP MAX and MIN are what the drain RTD saw during that time.","E is exhaust, drying included: 2:15. Z marks the end of the cycle, with the chamber already at 162°F.","3 minutes at about 271°F and an exhaust-plus-dry of only 2:15 most likely match the DART Warm-up cycle in the Century Medium cycle table (270°F, 3 min, 1 min dry): a warm-up cycle, not a load. That's why the leak test started right after (11:24).","The pressure column and a few decimals (x) can't be read in the photo."]}};

